import{_ as a,C as i,o as l,c as g,j as e,a as r,E as n,a2 as s}from"./chunks/framework.CdvW4CUT.js";const f=JSON.parse('{"title":"Atom and editor","description":"","frontmatter":{"title":"Atom and editor"},"headers":[],"relativePath":"en/guide/atom.md","filePath":"en/guide/atom.md"}'),d={name:"en/guide/atom.md"};function h(c,t,u,p,m,b){const o=i("Capture");return l(),g("div",null,[t[0]||(t[0]=e("h1",{id:"atom-and-editor",tabindex:"-1"},[r("Atom and editor "),e("a",{class:"header-anchor",href:"#atom-and-editor","aria-label":'Permalink to "Atom and editor"'},"​")],-1)),t[1]||(t[1]=e("p",null,[r("An "),e("strong",null,"atom"),r(" is a note in your memory: a Markdown file. This screen shows it for reading and, one click on "),e("strong",null,"Edit"),r(" later, turns it into a single text surface you can write in.")],-1)),n(o,{name:"atome-lecture",alt:"A note in reading mode: outline, properties and incoming links on the right, a warning callout and a table in the text."}),t[2]||(t[2]=s('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><ul><li><strong>The toolbar</strong>: <strong>Edit</strong> (which becomes <strong>Read</strong> while editing), <strong>Rename</strong>, <strong>Move</strong>, <strong>Remove</strong> and <strong>Export…</strong>.</li><li><strong>The header</strong>: the note&#39;s title, then a grey line with its zone, its path, its size and its date (&quot;modified 02.10.2026 · 12:00&quot;). The note&#39;s tags show as pills under that line.</li><li><strong>The text</strong>: headings, lists, tables, callouts and images, as the file describes them.</li><li><strong>The right-hand column</strong>: <ul><li><strong>OUTLINE</strong>: the note&#39;s headings. It only appears once there are two or more, and it disappears while editing: the editor has its own outline, opened with <strong>⌘⇧O</strong>.</li><li><strong>NOTE PROPERTIES</strong>: the fields from the top of the file (type, status, date…). <strong>Show the other property</strong> or <strong>Show the N other properties</strong> unfolds the rest, and <strong>Collapse to main properties</strong> folds it back.</li><li><strong>INCOMING LINKS</strong>: the notes that cite this one, with their date. If none does, the column says so: &quot;No note relies on this one&quot;.</li></ul></li><li><strong>While editing</strong>, three things are added (more below): the margin that names every block, a <strong>MEMORY</strong> panel in the right-hand column, and a status bar under the text: <strong>Line 7 · Markdown · UTF-8 · Saved</strong>, then <strong>Cancel</strong> and <strong>Save</strong>.</li></ul><p>In a narrow window the right-hand column moves below the text. The <strong>Collapse properties, outline and links</strong> button (or <strong>Show properties, outline and links</strong>) closes and reopens it.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="read-a-note" tabindex="-1">Read a note <a class="header-anchor" href="#read-a-note" aria-label="Permalink to &quot;Read a note&quot;">​</a></h3><p>Scroll the text. In the right-hand column, click a heading in the <strong>OUTLINE</strong> to jump to it, or a line in <strong>INCOMING LINKS</strong> to open the note that cites this one.</p><ul><li>A link to another note (<code>[[…]]</code>) is clickable and opens that note in a tab.</li><li>A link whose target does not exist stays visible but leads nowhere. Hover it: &quot;No note named … — this link needs fixing&quot;.</li><li>A link to a web address is not clickable. The address shows when you hover it.</li><li>A task-list checkbox ticks with one click, even in reading mode: the file is updated. If the write fails, a message tells you and asks you to reopen the note.</li></ul><h3 id="edit-a-note" tabindex="-1">Edit a note <a class="header-anchor" href="#edit-a-note" aria-label="Permalink to &quot;Edit a note&quot;">​</a></h3><p>Click <strong>Edit</strong>. The text becomes <strong>one Markdown surface</strong>: you type straight into it, as on a page.</p>',9)),n(o,{name:"atome-edition",alt:'The note in editing mode: the margin names each block (H1, ¶, H2, bullets, callout) and, hovering a block, the "+" handle and the drag grip appear.'}),t[3]||(t[3]=s('<p>Away from the line your cursor is on, you see the result: big headings, bold in bold. On the cursor&#39;s line the syntax appears (<code>#</code>, <code>**</code>, <code>[[…]]</code>) so you can change it. As soon as you move to another line, it folds away.</p><p>The file stays ordinary Markdown: the editor adds nothing to it.</p><h3 id="save-or-cancel" tabindex="-1">Save or cancel <a class="header-anchor" href="#save-or-cancel" aria-label="Permalink to &quot;Save or cancel&quot;">​</a></h3><p>The status bar under the text tells you where you stand: <strong>Saved</strong>, or <strong>Modified</strong> when some text is unsaved. A dot also shows on the note&#39;s tab.</p><ul><li><strong>Save</strong> writes the file. The button stays greyed out until something changes. The editor stays open after saving, and your undo history is kept.</li><li><strong>Cancel</strong> closes the editor and returns to reading, without saving.</li><li><strong>⌘Z</strong> undoes the last action, <strong>⌘⇧Z</strong> redoes it.</li><li>If the editor refuses to write (the text would no longer match what it read), a message says so and nothing is written.</li></ul><p>A tab with unsaved changes refuses to close: save or cancel first. Quitting Kessho with unsaved text asks you to confirm; you can turn that question off in <a href="/en/guide/settings.html">Settings</a> &gt; <strong>Appearance</strong>.</p><h3 id="read-the-margin" tabindex="-1">Read the margin <a class="header-anchor" href="#read-the-margin" aria-label="Permalink to &quot;Read the margin&quot;">​</a></h3><p>To the left of the text, the margin names each block with a sign: <strong>H1</strong> to <strong>H6</strong> for headings, <strong>¶</strong> for a paragraph, <strong>•</strong> for a bulleted list, <strong>1.</strong> for a numbered list, <strong>☐</strong> for a task list, <strong>❝</strong> for a quote, <strong>!</strong> for a callout, <strong>&lt;/&gt;</strong> for code, <strong>▦</strong> for a table, <strong>▣</strong> for an image, <strong>⧉</strong> for an embed, <strong>—</strong> for a rule. A list carries one sign, on its first line.</p><p>The margin is display only: it writes nothing to the file. When the window is too narrow, it folds away.</p><h3 id="move-duplicate-or-delete-a-block" tabindex="-1">Move, duplicate or delete a block <a class="header-anchor" href="#move-duplicate-or-delete-a-block" aria-label="Permalink to &quot;Move, duplicate or delete a block&quot;">​</a></h3><p>Hover a block: two buttons appear in the margin, a <strong>+</strong> and a six-dot grip.</p>',11)),n(o,{name:"menu-bloc",alt:"The block menu, opened by clicking the handle: turn into, duplicate, move up, move down, delete."}),t[4]||(t[4]=s("<ul><li><strong>Drag the grip</strong> to move the block. Hold <strong>⌥</strong> to copy it instead of moving it. <strong>Esc</strong> cancels the drag.</li><li><strong>Click the grip</strong> (without moving): the block is selected and its menu opens. <ul><li><strong>Turn into…</strong> opens the <code>/</code> menu so you can change the block&#39;s type.</li><li><strong>Duplicate</strong> (⌘D) copies the block right below.</li><li><strong>Move up</strong> (⌘⌥↑) and <strong>Move down</strong> (⌘⌥↓) shift it by one step. <strong>Move up</strong> is greyed out on the first block.</li><li><strong>Delete</strong> (⌫) removes it.</li></ul></li></ul><p>A list moves, duplicates and deletes as one block: it is never cut in two.</p>",2)),n(o,{name:"glisser-bloc",alt:'A block dragged by its handle: the "Move" banner names the destination and the insertion line sits before "Choosing rails".'}),t[5]||(t[5]=s('<h3 id="add-a-block-with-the" tabindex="-1">Add a block with the + <a class="header-anchor" href="#add-a-block-with-the" aria-label="Permalink to &quot;Add a block with the +&quot;">​</a></h3><p>The margin&#39;s <strong>+</strong> (&quot;Add a block below&quot;) creates an empty paragraph under the hovered block and opens the <code>/</code> menu on it straight away.</p><h3 id="pick-a-block-s-type-with-the-menu" tabindex="-1">Pick a block&#39;s type with the / menu <a class="header-anchor" href="#pick-a-block-s-type-with-the-menu" aria-label="Permalink to &quot;Pick a block&#39;s type with the / menu&quot;">​</a></h3><p>Type <code>/</code> at the very start of a line. The <strong>Block commands</strong> menu opens.</p>',4)),n(o,{name:"menu-slash",alt:'The "/" menu opened on a new paragraph: paragraph, headings, lists, quote, code, table, callout, rule.'}),t[6]||(t[6]=s('<p>It offers: <strong>Paragraph</strong>, <strong>Heading level 1</strong> to <strong>6</strong>, <strong>List</strong>, <strong>Numbered list</strong>, <strong>Task list</strong>, <strong>Quote</strong>, <strong>Code</strong>, <strong>Table</strong>, <strong>Callout</strong>, <strong>Foldable block</strong> and <strong>Horizontal rule</strong>.</p><ul><li>Keep typing to filter: <code>/tab</code> keeps only <strong>Table</strong>.</li><li><strong>↑</strong> and <strong>↓</strong> move through the list, <strong>Enter</strong> or <strong>Tab</strong> picks, <strong>Esc</strong> closes.</li><li>A <code>/</code> in the middle of a text (a date, a path) opens nothing.</li></ul><h3 id="format-text" tabindex="-1">Format text <a class="header-anchor" href="#format-text" aria-label="Permalink to &quot;Format text&quot;">​</a></h3><p>Select some words: the <strong>Formatting</strong> bar appears above the selection. It has five buttons: <strong>Bold</strong> (B), <strong>Italic</strong> (I), <strong>Strikethrough</strong> (S), <strong>Highlight</strong> (H) and <strong>Inline code</strong> (&lt;/&gt;). Clicking an already active button removes the formatting.</p>',4)),n(o,{name:"barre-de-format",alt:"A sentence selected in the editor: the formatting bar (bold, italic, strikethrough, highlight, code) appears right above it."}),t[7]||(t[7]=e("p",null,"The same actions have shortcuts (list below). Clicking in the bar does not lose your selection.",-1)),t[8]||(t[8]=e("h3",{id:"work-in-a-table",tabindex:"-1"},[r("Work in a table "),e("a",{class:"header-anchor",href:"#work-in-a-table","aria-label":'Permalink to "Work in a table"'},"​")],-1)),t[9]||(t[9]=e("p",null,"A table is written in Markdown, but you handle it with the mouse and the keyboard.",-1)),n(o,{name:"menu-cellule",alt:'The "/" menu in a table cell: insert or delete a row or column, align the column.'}),t[10]||(t[10]=s('<ul><li><strong><code>/</code> menu in a cell</strong>: type <code>/</code> at the start of a cell. In the table body, the menu offers nine entries: <strong>Insert row above</strong>, <strong>Insert row below</strong>, <strong>Delete row</strong>, <strong>Insert column left</strong>, <strong>Insert column right</strong>, <strong>Delete column</strong>, then <strong>Align left</strong>, <strong>Align center</strong> and <strong>Align right</strong>. In the header row it offers only seven: <strong>Insert row above</strong> and <strong>Delete row</strong> are not there. <strong>Delete column</strong> is not offered when the table has a single column.</li><li><strong>Tab</strong> moves to the next cell, <strong>⇧Tab</strong> to the previous one. <strong>Tab</strong> in the last cell adds a row.</li><li><strong>⌘↵</strong> adds a row below. <strong>⌥Tab</strong> adds a column.</li><li><strong>⌘⌥⏎</strong> adds a row, <strong>⌘⌥⇧⏎</strong> a column, <strong>⌘⌥⌫</strong> removes the row, <strong>⌘⌥⇧⌫</strong> removes the column.</li></ul><p>If the table has no valid separator line, the editor asks you to fix it by hand before you use these actions.</p><h3 id="add-a-callout" tabindex="-1">Add a callout <a class="header-anchor" href="#add-a-callout" aria-label="Permalink to &quot;Add a callout&quot;">​</a></h3><p>Pick <strong>Callout</strong> (or <strong>Foldable block</strong>) in the <code>/</code> menu. A callout is a Markdown quote whose first line is <code>&gt; [!type]</code>.</p>',4)),n(o,{name:"encadre-type",alt:"The callout type menu, opened from its header: note, tip, warning, danger, quote, with the fold options."}),t[11]||(t[11]=s('<ul><li>Put the cursor on the header line: the type word (<code>note</code>, <code>warning</code>…) becomes a button. Click it, or press <strong>⌥↵</strong>, to open the <strong>Callout type</strong> menu: <strong>Note</strong>, <strong>Tip</strong>, <strong>Warning</strong>, <strong>Danger</strong>, <strong>Quote</strong>.</li><li>In the same menu, <strong>Folded by default</strong> and <strong>Not foldable</strong> set the folding. A foldable callout has a chevron (<strong>Collapse</strong> / <strong>Expand</strong>).</li></ul><h3 id="add-an-image" tabindex="-1">Add an image <a class="header-anchor" href="#add-an-image" aria-label="Permalink to &quot;Add an image&quot;">​</a></h3><p>Paste an image, or drag an image file into the text. Accepted formats are png, jpg, gif and webp, up to 10 MB; anything larger is not added and a message tells you. The image is stored with your memory and a link is written in the note.</p><ul><li>Drag the handles on the sides of the image to change its width.</li><li><strong>Add a caption</strong>: the field under the image. The caption becomes the image&#39;s alt text.</li><li>Select the image and press <strong>⌫</strong>: it leaves the text, the file stays in your memory.</li></ul><h3 id="link-your-notes" tabindex="-1">Link your notes <a class="header-anchor" href="#link-your-notes" aria-label="Permalink to &quot;Link your notes&quot;">​</a></h3><ul><li>Type <code>[[</code>: a list of notes offers targets (eight at most). Type <code>#</code> to get tag suggestions. <strong>↑</strong> <strong>↓</strong> move through them, <strong>Enter</strong> or <strong>Tab</strong> picks.</li><li><strong>⌘K</strong> opens the <strong>Link</strong> window: <strong>Displayed text</strong>, then <strong>Destination: memory note or web address</strong>. It shows what will be written to the file (&quot;Will be written to the file&quot;). <strong>Insert</strong> confirms.</li><li><strong>⌘ + click</strong> on a <code>[[…]]</code> link opens the note it points to.</li><li>In the <strong>MEMORY</strong> panel in the right-hand column, <strong>Filter notes</strong> looks up a note. Drag it into the text: a choice appears at the drop point, <strong>Link</strong> (key 1) or <strong>Inclusion, content shown</strong> (key 2). <strong>Esc</strong> cancels.</li></ul>',6)),n(o,{name:"lien",alt:"The link window on selected text: typing the destination offers the matching notes and shows what will be written in the file."}),t[12]||(t[12]=e("h3",{id:"select-and-move-paragraphs",tabindex:"-1"},[r("Select and move paragraphs "),e("a",{class:"header-anchor",href:"#select-and-move-paragraphs","aria-label":'Permalink to "Select and move paragraphs"'},"​")],-1)),t[13]||(t[13]=e("p",null,[e("strong",null,"Esc"),r(' in the text selects the block under the cursor. The bar above the status bar then reads "N paragraphs · ⌥↑↓ move · / transform · ⌫ delete".')],-1)),n(o,{name:"selection-blocs",alt:'After Esc, the selection rounds up to whole blocks: the touched paragraphs are highlighted and the bottom bar announces "3 paragraphs" with their gestures.'}),t[14]||(t[14]=s('<ul><li><strong>⇧↑</strong> and <strong>⇧↓</strong> extend the selection.</li><li><strong>⌥↑</strong> and <strong>⌥↓</strong> move the selected paragraphs.</li><li><strong>/</strong> transforms them, <strong>⌫</strong> deletes them, <strong>⌘C</strong> and <strong>⌘X</strong> copy or cut them.</li></ul><h3 id="find-and-replace" tabindex="-1">Find and replace <a class="header-anchor" href="#find-and-replace" aria-label="Permalink to &quot;Find and replace&quot;">​</a></h3><p><kbd>⌘F</kbd> opens the <strong>Find and replace</strong> window, <kbd>⌘⌥F</kbd> opens it on the replace tab. It has three tabs: <strong>Find</strong>, <strong>Replace</strong> and <strong>In the memory</strong>, which searches all your notes and lists those that contain the text.</p>',3)),n(o,{name:"recherche-remplacer",alt:'The Find and replace window, Replace tab: "rail" is typed, the six occurrences are marked in the note and the replacement text is ready.'}),t[15]||(t[15]=s('<ul><li>Options: <strong>Match case</strong>, <strong>Whole word</strong>, <strong>Regular expression</strong> (<strong>Invalid expression</strong> if it is not written correctly) and <strong>Wrap around</strong>.</li><li><strong>Scope</strong> is set to <strong>Note</strong> or <strong>Selection</strong>.</li><li>The counter reads &quot;2 of 4&quot;; <strong>Previous</strong> and <strong>Next</strong> step through the matches.</li><li><strong>Replace</strong> changes the current match, <strong>Replace all</strong> changes every one. <strong>⌘Z</strong> undoes <strong>Replace all</strong> in one go.</li><li>If the selected text fits on one line, it fills the search field.</li></ul><h3 id="see-the-outline" tabindex="-1">See the outline <a class="header-anchor" href="#see-the-outline" aria-label="Permalink to &quot;See the outline&quot;">​</a></h3><p><strong>⌘⇧O</strong> shows or hides the note&#39;s <strong>Outline</strong> in the right-hand column. Click a heading to jump to it. Drag a heading in the outline: its whole section moves with it.</p>',3)),n(o,{name:"plan",alt:"The note outline, open at the top of the right panel: title and sections, to jump through the text."}),t[16]||(t[16]=e("h3",{id:"export-or-print",tabindex:"-1"},[r("Export or print "),e("a",{class:"header-anchor",href:"#export-or-print","aria-label":'Permalink to "Export or print"'},"​")],-1)),t[17]||(t[17]=e("p",null,[e("strong",null,"Export…"),r(" (toolbar) or "),e("strong",null,"⌘⇧E"),r(" opens the "),e("strong",null,"Export the note"),r(" window, with a preview. For HTML it follows your settings; for PDF it only reflects the page and margins, not the theme or the included items.")],-1)),n(o,{name:"export",alt:"A note's export window: format, page, margins, theme and content to include, with the page preview on the left."}),t[18]||(t[18]=s('<ul><li><strong>Format</strong>: <strong>HTML (standalone file)</strong> or <strong>PDF (system print)</strong>.</li><li><strong>Page</strong>: <strong>A4</strong> or <strong>US Letter</strong>. <strong>Margins</strong>: <strong>Narrow</strong>, <strong>Normal</strong> or <strong>Wide</strong>. <strong>Theme</strong>: <strong>Light</strong>, <strong>Dark</strong> or <strong>Follow the system</strong>.</li><li><strong>Include</strong>: <strong>Note title</strong>, <strong>Table of contents</strong>, <strong>Properties (frontmatter)</strong>, <strong>Open collapsed callouts</strong>.</li><li><strong>Destination</strong> (HTML): <strong>Downloads</strong>, <strong>Documents</strong> or <strong>Desktop</strong>. For PDF, the button becomes <strong>Print…</strong> and the system print window asks for the name and destination.</li><li>Your settings are remembered note by note, on this computer.</li></ul><p><strong>⌘P</strong> prints the note directly while you are editing.</p><h3 id="the-shortcuts-and-how-to-change-them" tabindex="-1">The shortcuts, and how to change them <a class="header-anchor" href="#the-shortcuts-and-how-to-change-them" aria-label="Permalink to &quot;The shortcuts, and how to change them&quot;">​</a></h3><p>Here are the default keys on a Mac. On Windows, <strong>⌘</strong> becomes <strong>Ctrl</strong> and <strong>⌥</strong> becomes <strong>Alt</strong>.</p><table tabindex="0"><thead><tr><th>Action</th><th>Keys</th></tr></thead><tbody><tr><td>Undo / Redo</td><td>⌘Z / ⌘⇧Z (or ⌃Y)</td></tr><tr><td>Bold, Italic</td><td>⌘B, ⌘I</td></tr><tr><td>Strikethrough, Highlight</td><td>⌘⇧S, ⌘⇧H</td></tr><tr><td>Inline code</td><td>⌘E</td></tr><tr><td>Heading 1 to 6, Paragraph</td><td>⌘⌥1 to ⌘⌥6, ⌘⌥0</td></tr><tr><td>Numbered list, Bulleted list, Task list</td><td>⌘⇧7, ⌘⇧8, ⌘⇧9</td></tr><tr><td>Quote, Code block</td><td>⌘⌥Q, ⌘⌥C</td></tr><tr><td>Move block up, Move block down, Duplicate block</td><td>⌘⌥↑, ⌘⌥↓, ⌘D</td></tr><tr><td>Insert a link</td><td>⌘K</td></tr><tr><td>Find, Replace</td><td>⌘F, ⌘⌥F</td></tr><tr><td>Outline, Export, Print</td><td>⌘⇧O, ⌘⇧E, ⌘P</td></tr><tr><td>Add a table row, column</td><td>⌘⌥⏎, ⌘⌥⇧⏎</td></tr><tr><td>Remove the table row, column</td><td>⌘⌥⌫, ⌘⌥⇧⌫</td></tr></tbody></table><p>These shortcuts only work in the editor. To change one, open <a href="/en/guide/settings.html">Settings</a> &gt; <strong>Shortcuts</strong>, <strong>In the editor</strong> section: click <strong>Change</strong> next to the action, then type the combination you want. <strong>Esc</strong> cancels. A combination without <strong>⌘</strong> (or <strong>Ctrl</strong>), one reserved by the system or one already used by another action is refused, with the reason. <strong>Reset</strong> puts the original keys back for that action, <strong>Reset all</strong> for every action.</p>',6))])}const k=a(d,[["render",h]]);export{f as __pageData,k as default};
